/* A polygon hit produced by the background-collision system.
 *
 * ROM RTTI records dBgPc as the sole base. dBgPi introduces the hierarchy's
 * first virtual function, so mwccarm places its vptr at 0x00 and dBgPc at
 * 0x04. The remaining fields begin at 0x18. This is the layout generated by
 * the pinned compiler and the one used by the C1/C2/D1 ROM bodies.
 */
#ifndef DBGPI_H
#define DBGPI_H
#include "dBgPc.h"

struct dActor_c;
struct dBgW;

struct dBgPi : dBgPc {
    /* 0x00 is the vptr; the dBgPc base occupies 0x04..0x17. */
    u16 triangleID;         /* 0x018 */
    /* Which registered collider produced this result: the slot index into
       the 0x18-entry table data_020a0c80, written by the DetectClsn loops.
       0x18 is the empty sentinel -- Reset stores it and the validity tests
       reject it. */
    u16 colliderIdx;        /* 0x01a */
    /* The hitting collider's identity: its ownerUniqueID, its owner and the
       collider itself, recorded together by SetCollider so IsHitBy can test
       the triplet. */
    s32 clsnID;             /* 0x01c */
    struct dActor_c *owner; /* 0x020 */
    struct dBgW *collider;  /* 0x024 */

    /* --- vtable, in ROM order. Do not reorder. --- */
    virtual ~dBgPi();       /* slots 0 (D1), 1 (D0) */

    /* Defined out of line; objisolate retains the enrolled C1/D1 variants and
       the compiler-generated siblings remain separately enrolled shells. */
    dBgPi();

    /* methods */
    dBgPi &operator=(const dBgPi &other);
    void CopyTo(dBgPi &dst) const;
    u32 GetClsnID() const;
    struct dActor_c *GetOwner() const;

    int GetColliderIndex() const;
    void SetColliderIndex(int idx);
    int IsHitBy(int uid, struct dActor_c *owner, struct dBgW *collider) const;
    int IsValid() const;
    int HasCollider() const;
    void RecordHit(int triID, SurfaceInfo *src);
    void SetCollider(int idx, int uid, struct dActor_c *owner,
                     struct dBgW *collider);
    void Reset();
};

/* Size is the dBgPi's own span AND the stride of the three consecutive results
   dBgCh_SphCrr holds at 0x74/0x9c/0xc4 -- notes/collision-system.md 3.2. */
#ifndef SM64DS_PLATFORM_PC
/* ROM layout under mwccarm; host ABI divergence is tracked separately. */
typedef char dBgPi_size_must_be_0x28[sizeof(struct dBgPi) == 0x28 ? 1 : -1];
#endif

#endif
